package com.aditya.day13.order; import org.springframework.stereotype.Service; import java.util.*; @Service public class OrderStateMachine{Map<OrderStatus,Set<OrderStatus>> a=Map.of(OrderStatus.CREATED,Set.of(OrderStatus.CONFIRMED,OrderStatus.CANCELLED),OrderStatus.CONFIRMED,Set.of(OrderStatus.PAYMENT_PENDING,OrderStatus.CANCELLED),OrderStatus.PAYMENT_PENDING,Set.of(OrderStatus.PAID,OrderStatus.CANCELLED),OrderStatus.PAID,Set.of(OrderStatus.PREPARING),OrderStatus.PREPARING,Set.of(OrderStatus.READY_FOR_PICKUP),OrderStatus.READY_FOR_PICKUP,Set.of(OrderStatus.OUT_FOR_DELIVERY),OrderStatus.OUT_FOR_DELIVERY,Set.of(OrderStatus.DELIVERED)); public void move(FoodOrder o,OrderStatus n){if(!a.getOrDefault(o.getStatus(),Set.of()).contains(n))throw new IllegalStateException("Invalid transition");o.setStatus(n);}}